import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const p=JSON.parse('{"title":"Documentation map","description":"Information architecture and editing rules for the documentation site.","frontmatter":{"title":"Documentation map","description":"Information architecture and editing rules for the documentation site."},"headers":[],"relativePath":"reference/documentation-map.md","filePath":"reference/documentation-map.md","lastUpdated":1794433168000}'),o={name:"reference/documentation-map.md"};function r(s,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="one-question-one-authoritative-home" tabindex="-1">One question, one authoritative home <a class="header-anchor" href="#one-question-one-authoritative-home" aria-label="Permalink to &quot;One question, one authoritative home&quot;">​</a></h1><p>The site follows a reader&#39;s task rather than the repository&#39;s history.</p><table tabindex="0"><thead><tr><th>Section</th><th>Reader&#39;s question</th><th>Owns</th></tr></thead><tbody><tr><td>Start</td><td>Why does this exist, and what could I do?</td><td>Vision, capabilities and a fictional walkthrough</td></tr><tr><td>Design</td><td>What are the system&#39;s boundaries?</td><td>Modules, knowledge, streaming and workers</td></tr><tr><td>Build</td><td>What do I implement and verify next?</td><td>Reuse, roadmap, clean builds, twelve factors and labs</td></tr><tr><td>Reference</td><td>Where is the supporting detail?</td><td>Source audit, vocabulary and earlier alternatives</td></tr></tbody></table><h2 id="single-sources-of-truth" tabindex="-1">Single sources of truth <a class="header-anchor" href="#single-sources-of-truth" aria-label="Permalink to &quot;Single sources of truth&quot;">​</a></h2><p><a href="./../project/acceptance">Requirements</a> own acceptance IDs. The <a href="./../project/roadmap">roadmap</a> owns implementation order. The <a href="./../reuse/source-audit">source audit</a> owns donor findings. <a href="./../status">Status</a> distinguishes delivered artifacts from future work. Other pages link to these instead of copying their tables.</p><h2 id="writing-rules" tabindex="-1">Writing rules <a class="header-anchor" href="#writing-rules" aria-label="Permalink to &quot;Writing rules&quot;">​</a></h2><p>Lead with the answer. Keep entry pages short; send deeper detail to its canonical page. Explain a term before using its abbreviation. Give one realistic example and one meaningful limitation. Code blocks contain executable commands or clearly labelled design examples.</p><p>Use <strong>Available</strong>, <strong>Planned</strong>, <strong>Reference</strong>, or an explicit verification statement where status matters. A mock is not a working model, a build is not a deployment, and an authored test is not a test result.</p><h2 id="navigation-and-accessibility" tabindex="-1">Navigation and accessibility <a class="header-anchor" href="#navigation-and-accessibility" aria-label="Permalink to &quot;Navigation and accessibility&quot;">​</a></h2><p>Four primary items lead to short section hubs. Sidebars show the current section, not the entire archive. Search, outlines and status remain available. Preserve old URLs when reorganizing content.</p><p>Use descriptive links, one page H1, sequential headings, visible focus and responsive content. Tables may scroll; the whole page should not. Do not encode status by color alone.</p><h2 id="change-verification" tabindex="-1">Change verification <a class="header-anchor" href="#change-verification" aria-label="Permalink to &quot;Change verification&quot;">​</a></h2><p>Run <code>npm test</code> and <code>node scripts/check-ia.mjs</code> after a build. Review desktop, narrow-screen and dark-mode rendering separately. Keep Pages publication evidence distinct from build checks. See <a href="./../project/setup">publishing</a>.</p>',13)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
